package com.therighthon.rnr.common.block;
import com.therighthon.rnr.common.material.RNRMaterials.Rock; import java.util.Locale; import net.minecraft.util.StringRepresentable; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.Blocks; import net.minecraft.world.level.block.SoundType; import net.minecraft.world.level.block.state.BlockBehaviour; import net.minecraft.world.level.block.state.properties.NoteBlockInstrument; import net.minecraft.world.level.material.MapColor;
public enum StoneBlockType implements StringRepresentable { GRAVEL_ROAD((r,s)->new GravelPathBlock(properties(r).sound(SoundType.GRAVEL).strength(r.category().hardness(3.5f),4)),true), OVER_HEIGHT_GRAVEL((r,s)->new OverHeightBlock(properties(r).sound(SoundType.GRAVEL).strength(r.category().hardness(3.5f),4)),false), MACADAM_ROAD((r,s)->new MacadamPathBlock(properties(r).sound(SoundType.GRAVEL).strength(r.category().hardness(4f),5)),true), FLAGSTONES((r,s)->new StonePathBlock(properties(r).strength(r.category().hardness(5f),8)),true), SETT_ROAD((r,s)->new StonePathBlock(properties(r).strength(r.category().hardness(5f),8)),true), COBBLED_ROAD((r,s)->new StonePathBlock(properties(r).strength(r.category().hardness(5f),8)),true); public static final StoneBlockType[] VALUES=values(); private final java.util.function.BiFunction<Rock,StoneBlockType,Block> factory; private final boolean variants; StoneBlockType(java.util.function.BiFunction<Rock,StoneBlockType,Block> f,boolean v){factory=f;variants=v;} private static BlockBehaviour.Properties properties(Rock r){return BlockBehaviour.Properties.of().mapColor(r.color()).sound(SoundType.STONE).instrument(NoteBlockInstrument.BASEDRUM);} public boolean hasVariants(){return variants;} public Block create(Rock r){return factory.apply(r,this);} public Block createRockSlab(Rock r,StoneBlockType t){BlockBehaviour.Properties p=BlockBehaviour.Properties.of().mapColor(r.color()).sound(SoundType.STONE).strength(1.5f,10);return t==GRAVEL_ROAD?new GravelPathSlabBlock(p):t==MACADAM_ROAD?new MacadamPathSlabBlock(p):new StonePathSlabBlock(p);} public PathStairBlock createPathStairs(Rock r,StoneBlockType t){BlockBehaviour.Properties p=BlockBehaviour.Properties.of().mapColor(r.color()).sound(SoundType.STONE).strength(1.5f,10);return new PathStairBlock(()->Blocks.STONE.defaultBlockState(),p,t==MACADAM_ROAD?MacadamPathBlock.getDefaultSpeedFactor():t==GRAVEL_ROAD?GravelPathBlock.getDefaultSpeedFactor():StonePathBlock.getDefaultSpeedFactor());} public String getSerializedName(){return name().toLowerCase(Locale.ROOT);} }
